  1  let magnets = [];
  2  let dragged = null;
  3  
  4  function setup() {
  5    createCanvas(800, 600);
  6    rectMode(CENTER);
  7    textAlign(CENTER, CENTER);
  8    for (let i = 0; i < 6; i++) {
  9      magnets.push(new Magnet(random(150, width - 150), random(150, height - 150), random(TWO_PI)));
 10    }
 11  }
 12  
 13  function draw() {
 14    background(30, 32, 40);
 15  
 16    for (let i = 0; i < magnets.length; i++) {
 17      for (let j = i + 1; j < magnets.length; j++) {
 18        applyMagnetism(magnets[i], magnets[j]);
 19      }
 20    }
 21  
 22    for (let m of magnets) {
 23      if (m !== dragged) {
 24        m.update();
 25      }
 26      m.display();
 27    }
 28  
 29    fill(240);
 30    noStroke();
 31    textSize(14);
 32    text("Bouncy Magnets: Click and drag to move, press SPACE to add magnet", width / 2, 25);
 33  }
 34  
 35  function applyMagnetism(m1, m2) {
 36    let p1 = [m1.getNorth(), m1.getSouth()];
 37    let p2 = [m2.getNorth(), m2.getSouth()];
 38    let q = [1, -1];
 39  
 40    for (let i = 0; i < 2; i++) {
 41      for (let j = 0; j < 2; j++) {
 42        let diff = p5.Vector.sub(p2[j], p1[i]);
 43        let d = diff.mag();
 44        if (d < 15) d = 15;
 45        let forceMag = (q[i] * q[j] * 600) / sq(d);
 46        let f = diff.copy().normalize().mult(-forceMag);
 47        m1.applyForce(f, p1[i]);
 48        m2.applyForce(f.copy().mult(-1), p2[j]);
 49      }
 50    }
 51  }
