 53  class Magnet {
 54    constructor(x, y, angle) {
 55      this.pos = createVector(x, y);
 56      this.vel = createVector(random(-1, 1), random(-1, 1));
 57      this.angle = angle || 0;
 58      this.angVel = random(-0.02, 0.02);
 59      this.w = 70;
 60      this.h = 24;
 61      this.mass = 2;
 62    }
 63  
 64    getNorth() {
 65      return p5.Vector.add(this.pos, createVector(cos(this.angle), sin(this.angle)).mult(this.w * 0.3));
 66    }
 67  
 68    getSouth() {
 69      return p5.Vector.add(this.pos, createVector(cos(this.angle), sin(this.angle)).mult(-this.w * 0.3));
 70    }
 71  
 72    applyForce(f, pt) {
 73      this.vel.add(p5.Vector.div(f, this.mass));
 74      let r = p5.Vector.sub(pt, this.pos);
 75      let torque = r.x * f.y - r.y * f.x;
 76      this.angVel += torque / 800;
 77    }
 78  
 79    update() {
 80      this.vel.mult(0.98);
 81      this.angVel *= 0.95;
 82      this.pos.add(this.vel);
 83      this.angle += this.angVel;
 84  
 85      let pad = this.w / 2;
 86      if (this.pos.x < pad) { this.pos.x = pad; this.vel.x *= -0.85; }
 87      if (this.pos.x > width - pad) { this.pos.x = width - pad; this.vel.x *= -0.85; }
 88      if (this.pos.y < pad) { this.pos.y = pad; this.vel.y *= -0.85; }
 89      if (this.pos.y > height - pad) { this.pos.y = height - pad; this.vel.y *= -0.85; }
 90    }
 91  
 92    display() {
 93      push();
 94      translate(this.pos.x, this.pos.y);
 95      rotate(this.angle);
 96  
 97      stroke(255);
 98      strokeWeight(1.5);
 99  
100      fill(220, 60, 60);
101      rect(this.w / 4, 0, this.w / 2, this.h, 4);
102  
103      fill(60, 100, 220);
104      rect(-this.w / 4, 0, this.w / 2, this.h, 4);
105  
106      fill(255);
107      noStroke();
108      textSize(12);
109      text("N", this.w / 4, 0);
110      text("S", -this.w / 4, 0);
111      pop();
112    }
113  
114    contains(x, y) {
115      return dist(x, y, this.pos.x, this.pos.y) < this.w / 2;
116    }
117  }
