119  function mousePressed() {
120    for (let i = magnets.length - 1; i >= 0; i--) {
121      if (magnets[i].contains(mouseX, mouseY)) {
122        dragged = magnets[i];
123        dragged.vel.set(0, 0);
124        dragged.angVel = 0;
125        break;
126      }
127    }
128  }
129  
130  function mouseDragged() {
131    if (dragged) {
132      dragged.pos.set(mouseX, mouseY);
133      dragged.vel.set(mouseX - pmouseX, mouseY - pmouseY);
134    }
135  }
136  
137  function mouseReleased() {
138    dragged = null;
139  }
140  
141  function keyPressed() {
142    if (key === ' ') {
143      magnets.push(new Magnet(mouseX, mouseY, random(TWO_PI)));
144    }
145  }
